import logging
import six
from taf.ul.rfsw.ssh.features.base import Feature
from taf.ul.rfsw.ssh.exception import TXPowerRetrievingNotSupported, RetrieveTXPowerFailure
from multiprocessing import cpu_count  # python > 2.6
from multiprocessing.dummy import Pool  # thread pool for python2/3 compatible than asyncio


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def _retrieve_tx_powers_by_dapd(connection,
                                sudo_enabled=False,
                                unit_ips=None,
                                processes=None):
    if not unit_ips:
        unit_ips = [None]

    processes = processes or cpu_count()
    pool = Pool(processes=processes)

    async_results = []
    for unit_ip in unit_ips:
        cmd = _generate_tx_power_dapd_commands(unit_ip, sudo_enabled)
        async_results.append(pool.apply_async(_retrieve_tx_power_by_dapd,
                                              args=(connection,),
                                              kwds={'cmd': cmd}))
    pool.close()
    pool.join()
    return [result.get() for result in async_results]


def _generate_tx_power_dapd_commands(unit_ip=None, sudo_enabled=False):
    if unit_ip:
        if sudo_enabled:
            cmd = 'sudo ssh root@{} dapd -sq'.format(unit_ip)
        else:
            cmd = 'ssh root@{} dapd -sq'.format(unit_ip)
    else:
        if sudo_enabled:
            cmd = 'sudo dapd -sq'
        else:
            cmd = 'dapd -sq'
    return cmd


def _retrieve_tx_power_by_dapd(connection, cmd):
    """
    :return: tuple (output, exception)
    """
    try:
        output = connection.execute(cmd)
    except Exception as exp:
        return None, exp
    return output, None


_ru_vs_features = {
    'AEHC': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'chile',
             'params': {'unit_ips': ['192.168.100.3', '192.168.100.4', '192.168.100.5', '192.168.100.6',
                                     '192.168.100.7', '192.168.100.8', '192.168.100.9', '192.168.100.10']}},

    'AEQC': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'amber',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5']}},

    'AEQQ': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'amber',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5']}},

    'AEQV': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'amber',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5']}},

    'AEQY': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'amber',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5']}},

    'AEQZ': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'amber',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5']}},

    'AQQA': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'galvatron',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5',
                                     '192.168.101.6', '192.168.101.7', '192.168.101.8', '192.168.101.9']}},
    'AQQC': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'galvatron',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5',
                                     '192.168.101.6', '192.168.101.7', '192.168.101.8', '192.168.101.9']}},
    'AQQY': {'func': _retrieve_tx_powers_by_dapd, 'platform': 'galvatron',
             'params': {'unit_ips': ['192.168.101.2', '192.168.101.3', '192.168.101.4', '192.168.101.5',
                                     '192.168.101.6', '192.168.101.7', '192.168.101.8', '192.168.101.9']}}
}


def _retrieve_tx_power(ru_name, connection, sudo_enabled=False, processes=None):
    for ru in _ru_vs_features.keys():
        if ru == ru_name.upper():
            ru_feature_record = _ru_vs_features[ru_name]

            try:
                results = ru_feature_record['func'](connection,
                                                    sudo_enabled,
                                                    processes=processes,
                                                    **ru_feature_record['params'])
                outputs = []
                for output, exception in results:
                    outputs.append(output)
                    if exception:
                        six.raise_from(RetrieveTXPowerFailure(), exception)

                return outputs

            except RetrieveTXPowerFailure:
                raise
            except Exception as exp:
                six.raise_from(RetrieveTXPowerFailure(), exp)
            finally:
                pass

    else:
        raise TXPowerRetrievingNotSupported('ru {} is not supported for retrieving tx power, only {} are supported'.
                                            format(ru_name, list(_ru_vs_features.keys())))


class RetrieveTxPower(Feature):

    @classmethod
    def various_behavior_by_ru(cls):
        return True

    @classmethod
    def retrieve_supported_rus(cls):
        return list(_ru_vs_features.keys())

    def __init__(self, ru_name, connection, sudo_enabled=False, processes=None):
        self._ru_name = ru_name
        self._connection = connection
        self._sudo_enabled = sudo_enabled
        self._processes = processes or cpu_count()

    def run(self):
        return _retrieve_tx_power(self._ru_name,
                                  self._connection,
                                  sudo_enabled=self._sudo_enabled,
                                  processes=self._processes)
